package com.hospital.finance;

import com.alibaba.fastjson2.JSON;
import com.alibaba.fastjson2.JSONObject;
import com.hospital.dao.*;
import com.hospital.entity.*;
import com.hospital.finance.auth.LoginPasswordCodec;
import com.hospital.service.impl.*;
import com.hospital.web.PublicDoctorView;
import org.junit.jupiter.api.Test;
import org.springframework.test.util.ReflectionTestUtils;
import java.util.*;
import static org.mockito.Mockito.*;
import static org.junit.jupiter.api.Assertions.*;

class DoctorAccountPrivacyTest {
    @Test void publicDoctorDtoHasOnlyFiveAllowedFields(){Doctor d=new Doctor();d.setId(1);d.setName("Demo");d.setDepartment("Demo department");d.setExpert(1);d.setText("Demo text");d.setAge(40);d.setSex(1);d.setAddress("private-address");d.setCertId("private-cert");d.setLoginid(99);d.setUsername("private-user");d.setPassword("private-password");JSONObject json=JSON.parseObject(JSON.toJSONString(PublicDoctorView.from(Collections.singletonList(d)).get(0)));assertEquals(new HashSet<>(Arrays.asList("id","name","department","expert","text")),json.keySet());assertFalse(json.toJSONString().contains("private-"));}
    @Test void publicRegistrationCannotClaimDoctorIdentity(){LoginServiceImpl service=new LoginServiceImpl();LoginMapper logins=mock(LoginMapper.class);DoctorMapper doctors=mock(DoctorMapper.class);PatientMapper patients=mock(PatientMapper.class);ReflectionTestUtils.setField(service,"loginMapper",logins);ReflectionTestUtils.setField(service,"doctorMapper",doctors);ReflectionTestUtils.setField(service,"patientMapper",patients);when(doctors.getDoctorByCertId("known-doctor-id")).thenReturn(new Doctor());Login request=new Login();request.setUsername("attempt");request.setPassword("attempt-password");request.setCertId("known-doctor-id");assertTrue(service.regist(request).contains("只能由管理员"));verify(logins,never()).insert(any());verifyNoInteractions(patients);}
    @Test void legacyAndHashedCredentialsBothLogin(){for(String stored:Arrays.asList("OldSyntheticPassword",LoginPasswordCodec.encode("OldSyntheticPassword"))){LoginServiceImpl service=new LoginServiceImpl();LoginMapper mapper=mock(LoginMapper.class);ReflectionTestUtils.setField(service,"loginMapper",mapper);Login account=new Login();account.setId(22);account.setRole(2);account.setPassword(stored);when(mapper.findByUsername("demo")).thenReturn(account);when(mapper.migratePassword(eq(22),anyString(),anyString())).thenReturn(1);Login input=new Login();input.setUsername("demo");input.setPassword("OldSyntheticPassword");assertEquals("登录成功2",service.login(input));assertEquals(Integer.valueOf(22),input.getId());input.setPassword("wrong-password");assertEquals("密码错误",service.login(input));assertNull(input.getId());}}
    @Test void doctorDetailsNeverReturnHashAndUnboundProfileDoesNotQueryNullLogin(){DoctorServiceImpl service=new DoctorServiceImpl();DoctorMapper doctors=mock(DoctorMapper.class);LoginMapper logins=mock(LoginMapper.class);ReflectionTestUtils.setField(service,"doctorMapper",doctors);ReflectionTestUtils.setField(service,"loginMapper",logins);Doctor unbound=new Doctor();unbound.setId(1);when(doctors.selectByPrimaryKey(1)).thenReturn(unbound);assertNull(service.getDoctor(1).getPassword());verifyNoInteractions(logins);Doctor bound=new Doctor();bound.setId(2);bound.setLoginid(22);when(doctors.selectByPrimaryKey(2)).thenReturn(bound);Login account=new Login();account.setUsername("demo-doctor");account.setPassword(LoginPasswordCodec.encode("StrongDemoPassword"));when(logins.selectByPrimaryKey(22)).thenReturn(account);assertEquals("demo-doctor",service.getDoctor(2).getUsername());assertNull(bound.getPassword());}
    @Test void blankPasswordEditPreservesHashAndNewPasswordHashes(){DoctorServiceImpl service=new DoctorServiceImpl();DoctorMapper doctors=mock(DoctorMapper.class);LoginMapper logins=mock(LoginMapper.class);ReflectionTestUtils.setField(service,"doctorMapper",doctors);ReflectionTestUtils.setField(service,"loginMapper",logins);Doctor stored=new Doctor();stored.setId(1);stored.setLoginid(22);when(doctors.selectByPrimaryKey(1)).thenReturn(stored);Login account=new Login();account.setId(22);String old=LoginPasswordCodec.encode("OldDemoPassword");account.setPassword(old);when(logins.selectByPrimaryKey(22)).thenReturn(account);when(doctors.updateByPrimaryKey(any())).thenReturn(1);when(logins.updateByPrimaryKey(any())).thenReturn(1);Doctor request=new Doctor();request.setId(1);request.setLoginid(999);request.setPassword("");service.upDoctor(request);assertEquals(old,account.getPassword());assertEquals(Integer.valueOf(22),request.getLoginid());request.setPassword("NewDemoPassword");service.upDoctor(request);assertNotEquals("NewDemoPassword",account.getPassword());assertTrue(LoginPasswordCodec.matches(account.getPassword(),"NewDemoPassword"));}
}
